-- Adds the three new moulded candles and the three candle sets to the shop, LIVE and IN STOCK. 26 Nov 2026. Run once in Supabase -> SQL editor.
-- Christmas Tree (MC-013), Teddy (MC-014), Evening Ember / Classic Pillar (MC-015); Float & Bloom Trio (ST-001), Moulded Six (ST-002), Mini Bubble Trio (ST-003).
-- Each starts with a count of 99 so no order is lost to "Sold out". Every order takes one off the count. Set the real count, or 0 when it is really out, in Owner view -> Stock.
-- Add their photos in Owner view -> Photos & videos. Until a photo is added the shop shows the drawn candle.
-- Safe to run again: new products are added only if missing; products that already exist are made live, their price is set to the locked one, and a count of 0 or 1 is raised to 99 (a count you set higher is left alone).
-- It does not touch any other product, photos, orders or settings.
begin;
insert into products (id, data, sort, live) values ('bnt-prd-mc-013', $j${"id": "bnt-prd-mc-013", "name": "Christmas Tree", "cat": "candles", "type": "Moulded candle", "line": "A hand-moulded Christmas tree candle in green, white oud scent, 75 g.", "desc": "A hand-moulded Christmas tree candle in green, white oud scent, 75 g.", "notes": ["White Oud"], "smellsLike": "Soft white oud, clean and gentle.", "pyramid": {"top": ["Floral notes"], "heart": ["White oud"], "base": ["Musk"]}, "variants": [{"sku": "BNT-PRD-MC-013", "label": "75 g", "price": 299, "stock": 99}], "material": "Hand-moulded candle.", "size": "75 g", "weight": 75, "care": ["Let the first burn melt to the edges.", "Trim the wick to 5 mm before each light.", "Never leave a burning candle unattended."], "mood": ["fresh", "creative"], "space": ["workspace", "entrance"], "occ": ["festive", "just-because"], "gift": true, "art": "jar", "c": "#596C0B", "colour": "Green"}$j$::jsonb, 420, true) on conflict (id) do nothing;
insert into stock (sku, qty) values ('BNT-PRD-MC-013', 99) on conflict (sku) do nothing;
