-- If you ran the earlier draft version: make them live, set the locked prices (299, 99, 399) and raise a count of 0 or 1 to 99.
update products set live = true where id in ('bnt-prd-mc-013','bnt-prd-mc-014','bnt-prd-mc-015','bnt-prd-st-001','bnt-prd-st-002','bnt-prd-st-003');
update products set data = jsonb_set(data, '{variants,0,price}', '299'::jsonb) where id = 'bnt-prd-mc-013';
update products set data = jsonb_set(data, '{variants,0,price}', '99'::jsonb) where id = 'bnt-prd-mc-014';
update products set data = jsonb_set(data, '{variants,0,price}', '399'::jsonb) where id = 'bnt-prd-mc-015';
update stock set qty = 99, updated_at = now() where sku in ('BNT-PRD-MC-013','BNT-PRD-MC-014','BNT-PRD-MC-015','BNT-PRD-ST-001','BNT-PRD-ST-002','BNT-PRD-ST-003') and qty <= 1;
commit;

select id, data->>'name' as name, data->'variants'->0->>'price' as price, live, (select qty from stock where sku = upper(products.id)) as stock from products where id in ('bnt-prd-mc-013','bnt-prd-mc-014','bnt-prd-mc-015','bnt-prd-st-001','bnt-prd-st-002','bnt-prd-st-003');
